#[inductive(initialize)]
fn initialize_inductive(post: Self, backing_cells: Seq<CellId>, storage: Map<nat, cell::PointsTo<T>>) {
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        assert(post.storage.dom().contains(i));
        assert(!post.in_active_range(i));
    };
}

#[inductive(produce_start)]
fn produce_start_inductive(pre: Self, post: Self) {
    let tail = pre.producer.get_Idle_0();
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == tail {
            assert(post.producer == ProducerState::Producing(tail));
            assert(post.is_checked_out(i));
            assert(!post.storage.dom().contains(i));
        } else {
            assert(pre.valid_storage_at_idx(i));
            // is_checked_out: pre.producer = Idle(tail), so pre.is_checked_out(i) = consumer == Consuming(i)
            // post.producer = Producing(tail), i != tail so Producing(tail) != Producing(i)
            // post.is_checked_out(i) = (Producing(tail) == Producing(i)) || consumer == Consuming(i)
            //                        = false || consumer == Consuming(i)
            //                        = pre.is_checked_out(i)
            assert(post.is_checked_out(i) == pre.is_checked_out(i));
            // storage: post.storage = pre.storage.remove(tail), i != tail
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));
            if pre.storage.dom().contains(i) {
                assert(post.storage[i] == pre.storage[i]);
            }
            // in_active_range: head and tail (field) unchanged
            assert(post.in_active_range(i) == pre.in_active_range(i));
        }
    };
}

#[inductive(produce_end)]
fn produce_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    let tail = pre.producer.get_Producing_0();
    let next_tail = Self::inc_wrap(tail, pre.len());
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == tail {
            // Show is_checked_out is false: producer is now Idle(next_tail), consumer != Consuming(tail)
            match pre.consumer {
                ConsumerState::Idle(h) => {
                    assert(!post.is_checked_out(i));
                }
                ConsumerState::Consuming(h) => {
                    // not_overlapping says h != tail
                    assert(h != tail);
                    assert(!post.is_checked_out(i));
                }
            }
            // storage has i=tail inserted
            assert(post.storage.dom().contains(i));
            assert(post.storage[i] == perm);
            assert(post.storage[i].id() == post.backing_cells[i as int]);
            assert(post.storage[i].is_init());
            // Show post.in_active_range(tail): tail entered the active range
            // post.head = pre.head, post.tail = next_tail
            // Case 1: next_tail = tail + 1 (no wrap)
            // Case 2: next_tail = 0 (tail = len-1, wrap)
            let head = pre.head;
            let len = pre.len();
            if next_tail == tail + 1 {
                // No wrap: next_tail = tail + 1
                // next_tail != head (from not_overlapping in produce_start, but here we use
                // that post has not_overlapping: (Idle(next_tail), consumer)):
                // from pre.not_overlapping: (Producing(tail), consumer)
                // either Idle(h): inc_wrap(tail, len) != h, so next_tail != head
                // or Consuming(h): h != tail, inc_wrap != h so next_tail != head
                // So head != next_tail = tail + 1, i.e., head <= tail or head > tail+1
                if head <= next_tail {
                    // head <= tail+1 and head != tail+1 means head <= tail
                    assert(head <= tail);
                    // post.in_active_range: head <= tail, and next_tail = tail+1 > tail >= head
                    // so post.head = head <= post.tail = tail+1
                    // in_active_range(tail) = head <= tail < tail+1 = true
                    assert(post.in_active_range(i));
                } else {
                    // head > tail+1 = next_tail, so head > post.tail
                    // in_active_range(tail) = tail >= head || tail < next_tail
                    //   = (tail >= head) || (tail < tail+1) = false || true = true
                    assert(post.in_active_range(i));
                }
            } else {
                // Wrap: next_tail = 0, tail = len - 1
                // next_tail != head means 0 != head, so head >= 1
                // post.head = head >= 1 > 0 = post.tail, so post.head > post.tail
                // in_active_range(tail=len-1) = tail >= head || tail < 0
                //   = (len-1 >= head) || false = true (since head < len)
                assert(head >= 1);
                assert(post.in_active_range(i));
            }
        } else {
            assert(pre.valid_storage_at_idx(i));
            // is_checked_out preserved for i != tail
            assert(post.is_checked_out(i) == pre.is_checked_out(i));
            // storage at i unchanged
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));
            if pre.storage.dom().contains(i) {
                assert(post.storage[i] == pre.storage[i]);
            }
            // in_active_range: post.head = pre.head, post.tail = next_tail, pre.tail = tail
            // Need: in_active_range(i) with (head, next_tail) == in_active_range(i) with (head, tail)
            let head = pre.head;
            let len = pre.len();
            if next_tail == tail + 1 {
                // For i != tail, i < tail iff i < tail+1 (since i != tail means i < tail or i > tail)
                // Case analysis on head <= tail vs head > tail
                if head <= tail {
                    // pre.in_active_range(i) = head <= i < tail
                    // post.in_active_range(i): is head <= next_tail?
                    //   head <= tail < tail+1 = next_tail, so yes
                    // post.in_active_range(i) = head <= i < next_tail = head <= i < tail+1
                    // For i != tail: head <= i < tail+1 iff head <= i && i <= tail,
                    //   and since i != tail: head <= i && i < tail
                    //   = pre.in_active_range(i) ✓
                    assert(post.in_active_range(i) == pre.in_active_range(i));
                } else {
                    // head > tail
                    // Is head <= next_tail = tail+1? head > tail means head >= tail+1.
                    //   next_tail != head means head != tail+1, so head > tail+1.
                    // Actually wait: head > tail means head >= tail+1. head != tail+1 means head > tail+1.
                    // So head > tail+1 = next_tail
                    // pre.in_active_range(i) = i >= head || i < tail
                    // post.in_active_range: head > next_tail so post.in_active_range(i) = i >= head || i < next_tail
                    //   = i >= head || i < tail+1
                    //   = i >= head || (i < tail || i == tail)
                    //   = i >= head || i < tail || i == tail
                    // For i != tail: = i >= head || i < tail = pre.in_active_range(i) ✓
                    assert(post.in_active_range(i) == pre.in_active_range(i));
                }
            } else {
                // Wrap: next_tail = 0, tail = len-1
                // head >= 1 (from next_tail=0 != head)
                // head <= tail = len-1 (since head < len = tail+1)
                // pre.in_active_range(i): head <= tail, so = head <= i < tail = head <= i < len-1
                // post.in_active_range: head >= 1 > 0 = next_tail, so post.head > post.tail
                //   = i >= head || i < next_tail = i >= head || i < 0 = i >= head
                // For i in [0, len-2] (i != tail = len-1):
                //   head <= i < len-1 iff head <= i (since i < len-1 always for i <= len-2)
                //   i >= head iff head <= i
                //   ✓
                assert(post.in_active_range(i) == pre.in_active_range(i));
            }
        }
    };
}

#[inductive(consume_start)]
fn consume_start_inductive(pre: Self, post: Self) {
    let head = pre.consumer.get_Idle_0();
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            assert(post.consumer == ConsumerState::Consuming(head));
            assert(post.is_checked_out(i));
            assert(!post.storage.dom().contains(i));
        } else {
            assert(pre.valid_storage_at_idx(i));
            // is_checked_out: pre.consumer = Idle(head), post.consumer = Consuming(head)
            // pre.is_checked_out(i) = producer == Producing(i) || Idle(head) == Consuming(i) = producer == Producing(i)
            // post.is_checked_out(i) = producer == Producing(i) || Consuming(head) == Consuming(i)
            //                        = producer == Producing(i) || (i == head)
            //                        = producer == Producing(i) || false (since i != head)
            //                        = pre.is_checked_out(i) ✓
            assert(post.is_checked_out(i) == pre.is_checked_out(i));
            // storage: post.storage = pre.storage.remove(head), i != head
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));
            if pre.storage.dom().contains(i) {
                assert(post.storage[i] == pre.storage[i]);
            }
            // in_active_range: head (field) and tail (field) unchanged
            assert(post.in_active_range(i) == pre.in_active_range(i));
        }
    };
}

#[inductive(consume_end)]
fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
    let head = pre.consumer.get_Consuming_0();
    let next_head = Self::inc_wrap(head, pre.len());
    assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
        if i == head {
            // Show is_checked_out is false: consumer is now Idle, producer != Producing(head)
            match pre.producer {
                ProducerState::Idle(t) => {
                    assert(!post.is_checked_out(i));
                }
                ProducerState::Producing(t) => {
                    // not_overlapping says t != head
                    assert(t != head);
                    assert(!post.is_checked_out(i));
                }
            }
            // storage has i=head inserted
            assert(post.storage.dom().contains(i));
            assert(post.storage[i] == perm);
            assert(post.storage[i].id() == post.backing_cells[i as int]);
            assert(post.storage[i].is_uninit());
            // Show !post.in_active_range(head): head left the active range
            // post.head = next_head, post.tail = pre.tail
            // head != pre.tail (from consume_start requirement; tail unchanged here)
            let tail = pre.tail;
            let len = pre.len();
            if next_head == head + 1 {
                // No wrap
                // Is post.head <= post.tail?
                if next_head <= tail {
                    // post.in_active_range(head) = next_head <= head < tail
                    //   = head+1 <= head = false ✓
                    assert(!post.in_active_range(i));
                } else {
                    // next_head > tail, post.head > post.tail
                    // post.in_active_range(head) = head >= next_head || head < tail
                    //   = head >= head+1 (false) || head < tail
                    //   = false || (head < tail)
                    // From head != tail and pre.in_active_range(head):
                    //   pre has consumer = Consuming(head), which means head was in active range
                    //   pre.in_active_range(head): from valid_storage_at_idx(head) in pre
                    //   wait... in consume_start, we checked out head. So in pre of consume_end,
                    //   head is checked out (consumer = Consuming(head)), so storage doesn't have head.
                    //   pre.valid_storage_at_idx(head): is_checked_out(head) = true, !storage.dom().contains(head)
                    //   That's consistent; we don't know in_active_range(head) for the purpose of storage.
                    // Actually for in_active_range here: next_head > tail means head+1 > tail, so head >= tail.
                    //   head != tail (from consume_start). So head > tail.
                    //   post.in_active_range(head) = head >= next_head || head < tail
                    //   = head >= head+1 (false) || head < tail (false since head > tail)
                    //   = false ✓
                    assert(!post.in_active_range(i));
                }
            } else {
                // Wrap: next_head = 0, head = len-1
                // post.head = 0 <= tail = post.tail
                // post.in_active_range(head=len-1) = 0 <= len-1 < tail
                //   = len-1 < tail? No since tail < len = len-1+1, so tail <= len-1.
                //   tail != head = len-1 (from consume_start). So tail < len-1.
                //   len-1 < tail is false. ✓
                assert(!post.in_active_range(i));
            }
        } else {
            assert(pre.valid_storage_at_idx(i));
            // is_checked_out preserved for i != head
            assert(post.is_checked_out(i) == pre.is_checked_out(i));
            // storage at i unchanged
            assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));
            if pre.storage.dom().contains(i) {
                assert(post.storage[i] == pre.storage[i]);
            }
            // in_active_range: post.head = next_head, pre.head = head, post.tail = pre.tail
            let tail = pre.tail;
            let len = pre.len();
            if next_head == head + 1 {
                if head <= tail {
                    // head <= tail, head != tail (from consume_start), so head < tail
                    // next_head = head+1 <= tail (since head < tail means head+1 <= tail)
                    // pre.in_active_range(i): head <= tail, so head <= i < tail
                    // post.in_active_range: next_head = head+1 <= tail, so head+1 <= i < tail
                    // For i != head: head <= i < tail iff head+1 <= i < tail (since i != head means i > head) ✓
                    assert(post.in_active_range(i) == pre.in_active_range(i));
                } else {
                    // head > tail
                    // Is next_head <= tail? next_head = head+1 > head > tail, so no.
                    // pre.in_active_range: head > tail, so i >= head || i < tail
                    // post.in_active_range: head+1 > tail, so i >= head+1 || i < tail
                    // For i != head: i >= head iff i >= head+1 (since i != head means if i >= head then i > head hence i >= head+1) ✓
                    assert(post.in_active_range(i) == pre.in_active_range(i));
                }
            } else {
                // Wrap: next_head = 0, head = len-1
                // head != tail (from consume_start), head = len-1, tail < len-1, so tail < head.
                // pre.in_active_range: head > tail, so i >= head || i < tail
                //   = i >= len-1 || i < tail
                //   = (i == len-1) || i < tail  (since i < len)
                // post.in_active_range: post.head = 0 <= tail = post.tail
                //   = 0 <= i < tail = i < tail
                // For i != head = len-1: i in [0, len-2]
                //   pre.in_active_range(i): (i == len-1) || i < tail = false || i < tail = i < tail
                //   post.in_active_range(i): i < tail ✓
                assert(post.in_active_range(i) == pre.in_active_range(i));
            }
        }
    };
}

