                    // post.head = head >= 1 > 0 = post.tail, so post.head > post.tail
                    // in_active_range(tail=len-1) = tail >= head || tail < 0
                    //   = (len-1 >= head) || false = true (since head < len)
                    assert(head >= 1);
                    assert(post.in_active_range(i));
