                        //   = i >= head || (i < tail || i == tail)
                        //   = i >= head || i < tail || i == tail
                        // For i != tail: = i >= head || i < tail = pre.in_active_range(i) ✓
                        assert(post.in_active_range(i) == pre.in_active_range(i));
                    }
                } else {
                    // Wrap: next_tail = 0, tail = len-1
                    // head >= 1 (from next_tail=0 != head)
                    // head <= tail = len-1 (since head < len = tail+1)
                    // pre.in_active_range(i): head <= tail, so = head <= i < tail = head <= i < len-1
                    // post.in_active_range: head >= 1 > 0 = next_tail, so post.head > post.tail
