                    // next_tail != head (from not_overlapping in produce_start, but here we use
                    // that post has not_overlapping: (Idle(next_tail), consumer)):
                    // from pre.not_overlapping: (Producing(tail), consumer)
                    // either Idle(h): inc_wrap(tail, len) != h, so next_tail != head
                    // or Consuming(h): h != tail, inc_wrap != h so next_tail != head
                    // So head != next_tail = tail + 1, i.e., head <= tail or head > tail+1
                    if head <= next_tail {
                        // head <= tail+1 and head != tail+1 means head <= tail
                        assert(head <= tail);
                        // post.in_active_range: head <= tail, and next_tail = tail+1 > tail >= head
                        // so post.head = head <= post.tail = tail+1
                        // in_active_range(tail) = head <= tail < tail+1 = true
                        assert(post.in_active_range(i));
                    } else {
                        // head > tail+1 = next_tail, so head > post.tail
                        // in_active_range(tail) = tail >= head || tail < next_tail
                        //   = (tail >= head) || (tail < tail+1) = false || true = true
                        assert(post.in_active_range(i));
