                        // So head > tail+1 = next_tail
                        // pre.in_active_range(i) = i >= head || i < tail
                        // post.in_active_range: head > next_tail so post.in_active_range(i) = i >= head || i < next_tail
                        //   = i >= head || i < tail+1
                        //   = i >= head || (i < tail || i == tail)
                        //   = i >= head || i < tail || i == tail
                        // For i != tail: = i >= head || i < tail = pre.in_active_range(i) ✓
                        assert(post.in_active_range(i) == pre.in_active_range(i));
                    }
                } else {
                    // Wrap: next_tail = 0, tail = len-1
                    // head >= 1 (from next_tail=0 != head)
                    // head <= tail = len-1 (since head < len = tail+1)
                    // pre.in_active_range(i): head <= tail, so = head <= i < tail = head <= i < len-1
                    // post.in_active_range: head >= 1 > 0 = next_tail, so post.head > post.tail
                    //   = i >= head || i < next_tail = i >= head || i < 0 = i >= head
                    // For i in [0, len-2] (i != tail = len-1):
                    //   head <= i < len-1 iff head <= i (since i < len-1 always for i <= len-2)
                    //   i >= head iff head <= i
                    //   ✓
                    assert(post.in_active_range(i) == pre.in_active_range(i));
                }
            }
        };
        admit()
    }

    #[inductive(consume_start)]
    fn consume_start_inductive(pre: Self, post: Self) {
        let head = pre.consumer.get_Idle_0();
        assert forall|i: nat| 0 <= i && i < post.len() implies post.valid_storage_at_idx(i) by {
            if i == head {
                assert(post.consumer == ConsumerState::Consuming(head));
                assert(post.is_checked_out(i));
                assert(!post.storage.dom().contains(i));
            } else {
                assert(pre.valid_storage_at_idx(i));
                // is_checked_out: pre.consumer = Idle(head), post.consumer = Consuming(head)
                // pre.is_checked_out(i) = producer == Producing(i) || Idle(head) == Consuming(i) = producer == Producing(i)
                // post.is_checked_out(i) = producer == Producing(i) || Consuming(head) == Consuming(i)
                //                        = producer == Producing(i) || (i == head)
                //                        = producer == Producing(i) || false (since i != head)
                //                        = pre.is_checked_out(i) ✓
                assert(post.is_checked_out(i) == pre.is_checked_out(i));
                // storage: post.storage = pre.storage.remove(head), i != head
                assert(post.storage.dom().contains(i) == pre.storage.dom().contains(i));
                if pre.storage.dom().contains(i) {
                    assert(post.storage[i] == pre.storage[i]);
                }
                // in_active_range: head (field) and tail (field) unchanged
                assert(post.in_active_range(i) == pre.in_active_range(i));
            }
        };
        admit()
    }

    #[inductive(consume_end)]
    fn consume_end_inductive(pre: Self, post: Self, perm: cell::PointsTo<T>) {
        let head = pre.consumer.get_Consuming_0();
        let next_head = Self::inc_wrap(head, pre.len());
